{"command": "cd /workspace/cms && python3 -c "
import sqlite3
con = sqlite3.connect('ridgeline_cms.db')
cur = con.cursor()
for sid, cid, name in cur.execute('SELECT subject_id, case_id, full_name FROM subjects'):
    counts = {}
    for t in ['address_history','phones','vehicles','employment','social_media','notes']:
        if t in ('notes',):
            n = cur.execute('SELECT COUNT(*) FROM notes WHERE case_id=?', (cid,)).fetchone()[0]
        else:
            n = cur.execute('SELECT COUNT(*) FROM %s WHERE subject_id=?' % t, (sid,)).fetchone()[0]
        counts[t]=n
    print(cid, name, counts)
""}

{"command": "cd /workspace/cms && python3 -c "
import sqlite3
con = sqlite3.connect('ridgeline_cms.db')
outer = con.cursor(); inner = con.cursor()
for sid, cid, name in outer.execute('SELECT subject_id, case_id, full_name FROM subjects'):
    counts = {}
    for t in ['address_history','phones','vehicles','employment','social_media']:
        counts[t] = inner.execute('SELECT COUNT(*) FROM %s WHERE subject_id=?' % t, (sid,)).fetchone()[0]
    counts['notes'] = inner.execute('SELECT COUNT(*) FROM notes WHERE case_id=?', (cid,)).fetchone()[0]
    counts['field_logs'] = inner.execute('SELECT COUNT(*) FROM field_logs WHERE case_id=?', (cid,)).fetchone()[0]
    print(cid, name, counts)
""}

